INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('42e4c59d-6079-51c2-a3dc-e3961ea38f84', '6feb4a3e-3dbf-5240-a169-ddae787780b0', '8e1a3816-99f8-5a1b-a1f1-df66afba357c', 28, 28, 'ስለ ፡ እግዚአብሔር ፡ የደከምክ ፡ አንተም ፡ ዋጋህን ፡ ታገኛለህ ።'),
  ('2028381d-8116-5597-a548-05d544d24803', '6feb4a3e-3dbf-5240-a169-ddae787780b0', '8e1a3816-99f8-5a1b-a1f1-df66afba357c', 29, 29, 'ለምትሰጣቸወም ፡ ሰዎች ፡ ‹‹ትጸልዩለትና ፡ ስለ ፡ እርሱም ፡ ትማልዱ ፡ ዘንድ›› ፡ ዕገሌ ፡ ያቀረበውን ፡ ሰጠኋችሁ ፡ በላቸው ።'),
  ('aa737ad3-24e6-5242-a23e-3db5792031a2', '6feb4a3e-3dbf-5240-a169-ddae787780b0', '8e1a3816-99f8-5a1b-a1f1-df66afba357c', 30, 30, 'ለሰው ፡ ሁሉ ፡ በጎ ፡ ነገርን ፡ ታደርጉ ፡ ዘንድ ፡ ይገባል ። ለዚህ ፡ እሰጠዋለሁ ፣ ሌላውን ፡ እከለክለዋሁ ፡ አትበሉ ።'),
  ('4600e65a-6107-5db7-ad49-7a03fe01a558', '6feb4a3e-3dbf-5240-a169-ddae787780b0', '8e1a3816-99f8-5a1b-a1f1-df66afba357c', 31, 31, 'አንተም ፡ ኤጲስ ፡ ቆጶስ ፡ ማንንም ፡ አትለይ ፣ ፡ ጌታችን ፡ ለለመነህ ፡ ሁሉ ፡ ስጠው ፡ ብሏልና ፣ ፡ ይህንም ፡ ማለት ፡ ወዳጅህም ፡ ቢሆን ፣ ፡ ጠላትህም ፡ ቢሆን ፣ ፡ ዘመድህም ፡ ቢሆን ፣ ፡ ወይም ፡ ስደተኛ ፡ ቢሆን ፣ ፡ ወይም ፡ ያገባ ፡ ቢሆን ፣ ፡ ሚስት ፡ የሌለውም ፡ ቢሆን ፡ ባል ፡ የሌላትም ፡ ብትሆን ፡ እናት ፡ አባት ፡ የሞቱበትም ፡ ቢሆን ፣ ለሁሉም ፡ በጎ ፡ ነገርን ፡ አድርግ ።'),
  ('aa00139d-a3fe-5f4b-af68-fff6dc1b22e7', '6feb4a3e-3dbf-5240-a169-ddae787780b0', '8e1a3816-99f8-5a1b-a1f1-df66afba357c', 32, 32, 'ጌታችን ፡ ለችግረኞች ፡ እንራራላቸው ፡ ዘንድ ፡ በመጻሕፍት ፡ አዝዞናልና ።'),
  ('7815fe1f-3e60-5c82-ae2e-1b224fc9c93c', '6feb4a3e-3dbf-5240-a169-ddae787780b0', '8e1a3816-99f8-5a1b-a1f1-df66afba357c', 33, 33, 'በነቢዩ ፡ በኢሳይያስ ፡ እንጀራህን ፡ ለተራሰ ፡ ቍረስ ፣ ለድኃውም ፡ አብሳው ፣ በቤትህ ፡ ጥላ ፡ ውስጥም ፡ አሳድረው ፡ እንዳለ ።'),
  ('0e719522-1fa7-5eb3-aedd-b41f2ccc5adb', '6feb4a3e-3dbf-5240-a169-ddae787780b0', '8e1a3816-99f8-5a1b-a1f1-df66afba357c', 34, 34, 'የታረዘንም ፡ ብታይ ፡ አል ፡ ብሰው ፣ ፡ የሥጋ ፡ ዘመድህንም ፡ ቸል ፡ አትበል ።'),
  ('1a2a6c10-a264-532d-a8be-85497b718fb2', '6feb4a3e-3dbf-5240-a169-ddae787780b0', '8e1a3816-99f8-5a1b-a1f1-df66afba357c', 35, 35, 'ዳንኤልም ፡ ንጉሥ ፡ ሆይ ፡ ስለዚህ ፡ ነገር ፡ ምክሬ ፡ ደስ ፡ ያሰኝህ ፡ በእውነተኛ ፡ ምጽዋት ፡ ትድናለህ ፡ አለ ።'),
  ('29cf6387-64e2-57ed-a295-c6c2862ae231', '6feb4a3e-3dbf-5240-a169-ddae787780b0', '8e1a3816-99f8-5a1b-a1f1-df66afba357c', 36, 36, 'እግዚአብሔር ፡ በደልህን ፡ እስቲያቀልልህ ፡ ድረስ ፡ ኃጢአትህ ፡ ነዳያንን ፡ በመመጽወት ፡ ይሠረይልሃል ፡ አለ ።'),
  ('077bd69a-5f38-5557-a9e9-0477cb66c954', '6feb4a3e-3dbf-5240-a169-ddae787780b0', '8e1a3816-99f8-5a1b-a1f1-df66afba357c', 37, 37, 'ሁለትኛም ፡ ሰሎሞን ፡ በሃይማኖትና ፡ በመራራት ፡ ኃጢአት ፡ ይደመስሳል ፡ አለ ።'),
  ('2720c082-e73f-5da6-a9d7-bdf804378f9d', '6feb4a3e-3dbf-5240-a169-ddae787780b0', '8e1a3816-99f8-5a1b-a1f1-df66afba357c', 38, 38, 'ዳግመኛም ፡ ዳዊት ፡ ለችግረኛውና ፡ ለምስኪን ፡ የሚያስብ ፡ ብፁዕ ፡ ነው ። እግዚአብሔር ፡ ከክፉ ፡ ቀን ፡ ያድነዋል ፡ አለ ።'),
  ('51ee6d02-76f1-5ce0-af46-e7e5507cc31d', '6feb4a3e-3dbf-5240-a169-ddae787780b0', '8e1a3816-99f8-5a1b-a1f1-df66afba357c', 39, 39, 'ሁለተኛም ፡ ገንዘቡን ፡ በተነ ፣ ለደኃም ፡ ሰጠ ፣ ጽድቁም ፡ ለዘለዓለም ፡ ይኖራል ፡ አለ ።'),
  ('019e5007-35db-5d81-aa2c-7dd0777af389', '6feb4a3e-3dbf-5240-a169-ddae787780b0', '8e1a3816-99f8-5a1b-a1f1-df66afba357c', 40, 40, 'ዳግመኛም ፡ ሰሎሞን ፡ ለድኃ ፡ የሚራራ ፡ ለእግዚአብሔር ፡ ያበድራል ፡ እንደሰጠም ፡ ይቀበላል ።'),
  ('317cbfd9-88c1-59c9-a2df-ade21905ac50', '6feb4a3e-3dbf-5240-a169-ddae787780b0', '8e1a3816-99f8-5a1b-a1f1-df66afba357c', 41, 41, 'የድኃውን ፡ ጩኸት ፡ እንዳይሰማ ፡ ጆሮውን ፡ የሚደፍን ፣ የተገፋውንም ፡ እንዳያይ ፡ ዓይኑን ፡ የሚከድን ፣ እሱንም ፡ እግዚአብሔር ፡ ቸል ፡ ይለዋል ።'),
  ('3a8c412d-0ae6-5bfd-ae3a-e6abdb1552c1', '6feb4a3e-3dbf-5240-a169-ddae787780b0', '8e1a3816-99f8-5a1b-a1f1-df66afba357c', 42, 42, 'ባልቴቶች ፡ ትዕግሥተኞች ፡ ነገርን ፡ የማያበዙ ፣ ፡ ክፋትና ፡ ቍጣ ፡ የሌለባቸው ፡ ይሆኑ ፡ ዘንድ ፡ አገባብ ፡ ነው ።'),
  ('a1d9b359-0a2a-50fa-ab84-64a42aac38a5', '6feb4a3e-3dbf-5240-a169-ddae787780b0', '8e1a3816-99f8-5a1b-a1f1-df66afba357c', 43, 43, 'ነገር ፡ ግን ፡ እነሱ ፡ ንጹሖች ፡ እግዚአብሔርን ፡ በእውነት ፡ የሚያመልኩት ፡ ይሁኑ ።'),
  ('88601dee-d1bd-5e6b-a79d-11bb75778561', '6feb4a3e-3dbf-5240-a169-ddae787780b0', '8e1a3816-99f8-5a1b-a1f1-df66afba357c', 44, 44, 'ክፉ ፡ ሥራን ፡ ቢያዩ ፣ ክፉ ፡ ቃልንም ፡ ቢሰሙ ፡ እንዳላዩና ፡ እንዳልሰሙ ፡ ዝም ፡ ይበሉ ።'),
  ('806cfeb3-3d76-58f3-a758-a497c0cd960f', '6feb4a3e-3dbf-5240-a169-ddae787780b0', '8e1a3816-99f8-5a1b-a1f1-df66afba357c', 45, 45, 'የባልቴት ፡ አሳቧ ፡ ለቤተ ፡ ክርስቲያን ፡ መባ ፡ ለማግባት ፡ ስለሚመጡት ፡ ከመጸለይና ፡ ከመማለድ ፡ በቀር ፡ ሌላ ፡ ምንም ፡ አይሁን ።'),
  ('46b51e00-9c4c-5e57-a5d8-b0213d488845', '6feb4a3e-3dbf-5240-a169-ddae787780b0', '8e1a3816-99f8-5a1b-a1f1-df66afba357c', 46, 46, 'የተጠላ ፡ ከንቱ ፡ ነገርን ፡ የሚሻ ፡ ሰው ፡ ቢኖር ፡ አይመልሱለት ፡ ነገር ፡ ግን ፡ የሃይማኖትን ፡ ቃልና ፡ የጽድቅ ፡ ሥራን ፡ የሚፈልጉትን ፡ ይቀበሉ ፣ በእግዚአብሔር ፡ ዘንድም ፡ በጐ ፡ ነገርን ፡ ይሳተፉ ።'),
  ('857935ef-0ac8-58c3-aa0e-c924f6120f97', '6feb4a3e-3dbf-5240-a169-ddae787780b0', '8e1a3816-99f8-5a1b-a1f1-df66afba357c', 47, 47, 'ሥራትን ፡ ይማሩ ፡ ዘንድ ፡ የሚሹ ፡ ወደ ፡ መምህራን ፡ ሄደው ፡ ይማሩ ፡ የምክር ፡ ቃልንም ፡ ይስሙ ።'),
  ('03003faa-cab3-5475-a32f-64745e0fa374', '6feb4a3e-3dbf-5240-a169-ddae787780b0', '8e1a3816-99f8-5a1b-a1f1-df66afba357c', 48, 48, 'የነገር ፡ ሥራ ፡ ቃልን ፡ አይስሙ ፣ ፡ ልዩዎች ፡ አማልክትንም ፡ አይከተሉ ፣ ፡ ሁሉን ፡ የፈጠረ ፡ አንድ ፡ እግዚአብሔርን ፡ ያምልኩት ፡ እንጂ ።'),
  ('b89d9ea8-5166-506d-a8d1-52d7ea6538cb', '6feb4a3e-3dbf-5240-a169-ddae787780b0', '8e1a3816-99f8-5a1b-a1f1-df66afba357c', 49, 49, 'እግዚአብሔር ፡ መንግሥተ ፡ ሰማያትን ፡ ከአዝርእት ፡ ሁሉ ፡ በምታንስ ፡ የሰናፍጭ ፡ ቅንጣት ፡ መስሏታልና ፣ ፡ ሰው ፡ በቀመሳት ፡ ጊዜ ፡ ታቃጥለዋለች ። የሃይማኖት ፡ ትምህርት ፡ ቃል ፡ እንዲሁ ፡ ናት ፣ ፡ ሰይጣንን ፡ ታቃጥለዋለችና ።'),
  ('31b7cfa2-f4ba-5999-a7dc-390012e9ecf7', '6feb4a3e-3dbf-5240-a169-ddae787780b0', '8e1a3816-99f8-5a1b-a1f1-df66afba357c', 50, 50, 'የነቢያት ፡ ቃልን ፡ እንወነጅል ፡ ዘንድ ፡ አይገባም ። ሃይማኖትን ፡ ለካዱ ፡ ሰዎችም ፡ ምሥጢርን ፡ አንግለጽ ።'),
  ('aa85115d-2080-598a-a353-b2274760da4f', '6feb4a3e-3dbf-5240-a169-ddae787780b0', '8e1a3816-99f8-5a1b-a1f1-df66afba357c', 51, 51, 'ነገር ፡ ግን ፡ በሃይማኖት ፡ እንጽና ፣ ፡ «ጌታችን ፡ ዕንቈቻችሁን ፡ በእሪያዎች ፡ ፊት ፡ አትጣሉ ። የተቀደሰውንም ፡ ለውሾች ፡ አትስጡ ። ዕንቈቻችሁኝ ፡ በእግራቸው ፡ እንዳይጠቀጥቁት ፣ ፡ ተመልሰውም ፡ ይጥሏችኋል» ፡ ብሎ ፡ አዝዞናልና ። ከሐድያን ፡ በስንፍናቸው ፡ የምሥጢርን ፡ ነገር ፡ ባወቁ ፡ ጊዜ ፡ ይንቃሉ ። ኀፍረትና ፡ ውርደትንም ፡ ያደርጋሉ ።'),
  ('d5165160-00d6-5ac1-a67e-727fc66a0dc7', '6feb4a3e-3dbf-5240-a169-ddae787780b0', '8e1a3816-99f8-5a1b-a1f1-df66afba357c', 52, 52, 'ነገር ፡ ግን ፡ የኦሪትንና ፡ ስለ ፡ ክርስቶስ ፡ መምጣት ፡ ትንቢት ፡ የተናገሩ ፡ የነቢያትን ፡ ቃል ፡ ያስተውሉ ፡ ዘንድ ፡ አስተምሯቸው ፡ እንጂ ።'),
