  ('0cea115e-c086-5905-a73b-8b5c9501dad6', 'dd5a559a-4398-5d26-ac16-138d56a83cff', 'cc0f84f3-0e14-5b2c-acfe-23797f702f98', 13, 13, 'እናንተ ፡ ግን ፡ የታሠሩትን ፡ ለመጐብኘት ፡ ወደ ፡ እሥር ፡ ቤት ፡ መሄድን ፡ ቸል ፡ ትሉና ፡ ታፍሩ ፡ ዘንድ ፡ የተገባ ፡ አይደለም ፣ ፡ እርዷቸው ፡ አጥናኗቸው ፡ እንጂ ።'),
  ('313f031f-43f8-58c5-a7c6-63f8f6a2a74f', 'dd5a559a-4398-5d26-ac16-138d56a83cff', 'cc0f84f3-0e14-5b2c-acfe-23797f702f98', 14, 14, 'ይህን ፡ ብታደርጉ ፡ ከሰማዕታት ፡ ጋራ ፡ ትቆጠራላችሁ ፡ መከራን ፡ ስለ ፡ ተቀበሉ ፣ ፡ ስለ ፡ ተጨነቁም ፡ ምስክርነታቸው ፡ ተጽፏልና ።'),
  ('d0c504a4-bc53-55a6-a4e1-2fbbce9359ff', 'dd5a559a-4398-5d26-ac16-138d56a83cff', 'cc0f84f3-0e14-5b2c-acfe-23797f702f98', 15, 15, 'እናንተም ፡ በቈራጥ ፡ ልብና ፡ በመልካም ፡ አገልግሎት ፡ እነርሱን ፡ ያለ ፡ ስንፍና ፡ ስለ ፡ አገለገላችሁ ፡ ከእነርሱ ፡ ጋራ ፡ ተቆጥራችኋል ።'),
  ('648c2a5e-fed2-5950-a67b-bd2fd5453683', 'dd5a559a-4398-5d26-ac16-138d56a83cff', 'cc0f84f3-0e14-5b2c-acfe-23797f702f98', 16, 16, 'ስለእነዚህም ፡ ጌታችን ፡ እንዲህ ፡ አለ ፣ ፡ ዓለም ፡ ሳይፈጠር ፡ የተዘጋጀላችሁን ፡ መንግሥተ ፡ ሰማያትን ፡ ትወርሱ ፡ ዘንድ ፡ የአባቴ ፡ ቡሩካን ፡ ወደኔ ፡ ኑ ።'),
  ('5eb55c6f-71ee-593d-a093-e1f5fa696052', 'dd5a559a-4398-5d26-ac16-138d56a83cff', 'cc0f84f3-0e14-5b2c-acfe-23797f702f98', 17, 17, 'ብራብ ፡ አብልታችሁኛልና ፣ ፡ ብጠማም ፡ አጠጥታችሁኛልና ፣ እንግዳ ፡ ብሆን ፡ ተቀብላችሁኛልና ፣ ብታረዝ ፡ አልብሳችሁኛልና ፣ ፡ ብታመም ፡ ጐብኝታችሁኛልና ፣ ብታሠር ፡ ጠይቃችሁኛልና ።'),
  ('060963db-ad8e-5b93-a076-6e2c126b0770', 'dd5a559a-4398-5d26-ac16-138d56a83cff', 'cc0f84f3-0e14-5b2c-acfe-23797f702f98', 18, 18, 'ያን ፡ ጊዜም ፡ ጻድቃን ፡ እንደዚህ ፡ ብለው ፡ ይመልሳሉ ፣ ፡ አቤቱ ፡ መቼ ፡ ተርበህ ፡ አይተንህ ፡ አብልተን ፣ ፡ መቼስ ፡ ተጠምተህ ፡ አይተንህ ፡ አጠጥተንህ ፣ ፡ መቼ ፡ እንግዳ ፡ ሁነህ ፡ አይተንህ ፡ ተቀብለንህ ፣ መቼ ፡ ታርዘህ ፡ አይተንህ ፡ አልብሰን ፣ ፡ መቼ ፡ ታመህ ፡ አይተን ፡ ጐብኝተንህ ፣ ፡ መቼ ፡ ታሥረህ ፡ አይተንህ ፡ ጠይቀህ ፣ ፡ ብለው ፡ ይመልሱለታል ።'),
  ('1aae92c5-63e6-5e57-a8ce-1587100510bc', 'dd5a559a-4398-5d26-ac16-138d56a83cff', 'cc0f84f3-0e14-5b2c-acfe-23797f702f98', 19, 19, 'ንጉሡም ፡ እንደዚህ ፡ ብሎ ፡ ይመልስላቸዋል ። ከእነዚህ ፡ በእኔ ፡ ከሚያምኑ ፡ ከታናናሾቹ ፡ ወንድሞቼ ፡ ላንዱ ፡ ያደረጋችሁትን ፡ ለእኔ ፡ አደረጋችሁ ፡ ብዬ ፡ በእውነት ፡ እነግራችኋለሁ ።'),
  ('096225bd-8cc8-5b6d-ae08-cf08a7f3edb1', 'dd5a559a-4398-5d26-ac16-138d56a83cff', 'cc0f84f3-0e14-5b2c-acfe-23797f702f98', 20, 20, 'ከዚህ ፡ በኋላ ፡ በግራ ፡ ያሉትን ፡ እናንተ ፡ የተረገማችሁ ፡ ከእኔ ፡ ሒዱ ፡ ለዲያብሎስና ፡ ለሠራዊቱ ፡ ወደ ፡ ተዘጋጀ ፡ የዘለዓለም ፡ እሳት ፡ ሂዱ ፡ ይላቸዋል ።'),
  ('025f60e8-185d-5060-a8f9-96105a71a532', 'dd5a559a-4398-5d26-ac16-138d56a83cff', 'cc0f84f3-0e14-5b2c-acfe-23797f702f98', 21, 21, 'ብራብ ፡ አላበላችሁኝምና ፣ ፡ ብጠማ ፡ አላጠጣችሁኝምና ፣ ፡ እንግዳ ፡ ብሆን ፡ አልተቀበላችሁኝምና ፣ ፡ ብታረዝ ፡ አላለበሳችሁኝምና ፣ ፡ ብታመም ፡ አልጐብኛችሁኝምና ፣ ብታሠር ፡ አልጠየቃችሁምና ።'),
  ('470bb98e-e5d5-5b86-af7c-4fb56dd09b73', 'dd5a559a-4398-5d26-ac16-138d56a83cff', 'cc0f84f3-0e14-5b2c-acfe-23797f702f98', 22, 22, 'ያን ፡ ጊዜም ፡ በስተግራ ፡ ያሉት ፡ አባቱ ፡ ተርበህ ፡ አይተንህ ፡ ያላበላህ ፣ ፡ ተጠምተህ ፡ አይተንህ ፡ ያላጠጣንህ ፣ ፡ እንግዳ ፡ ሁነህ ፡ መጥተህ ፡ ያልተቀበልንህ ፣ ፡ ተርበህ ፡ አይተንህ ፡ ያላለበስንህ ፣ ፡ ታመህ ፡ አይተን ፡ ያልጠየቅንህ ፣ ፡ ታሥረህ ፡ አይተንህ ፡ ያልጐበኘህ ፡ መቼ ፡ ነው? ፡ እያሉ ፡ ይመልሱለታል ።'),
  ('4531fa9d-3bcf-5e7f-a0a5-ddb331339eb0', 'dd5a559a-4398-5d26-ac16-138d56a83cff', 'cc0f84f3-0e14-5b2c-acfe-23797f702f98', 23, 23, 'ከዚህም ፡ በኋላ ፡ ንጉሡ ፡ ከእነዚህ ፡ ከታናናሾቹ ፡ ለአንዱ ፡ ያላደረጋችሁት ፡ ለእኔ ፡ አለማድረጋችሁ ፡ ነው ፡ ብሎ ፡ ይመልስላቸዋል ።'),
  ('f9288f6b-a842-505b-abcb-49e3bb0249ff', 'dd5a559a-4398-5d26-ac16-138d56a83cff', 'cc0f84f3-0e14-5b2c-acfe-23797f702f98', 24, 24, 'እነርሱም ፡ ወደዘለዓለም ፡ ፍርድ ፡ ይሄዳሉ ።'),
  ('e183f7bf-40a5-52c9-aedc-ffe50e15ba31', 'dd5a559a-4398-5d26-ac16-138d56a83cff', 'cc0f84f3-0e14-5b2c-acfe-23797f702f98', 25, 25, 'ጻድቃን ፡ ግን ፡ ወደዘለዓለም ፡ ሕይወት ፡ ይሄዳሉ ።'),
  ('1524405b-02ef-597a-aaf2-43023a498b96', 'dd5a559a-4398-5d26-ac16-138d56a83cff', 'cc0f84f3-0e14-5b2c-acfe-23797f702f98', 26, 26, 'እኔ ፡ ክርስቲያን ፡ ነኝ ፡ የሚል ፡ ክፉ ፡ ሥራን ፡ የሚሠራ ፣ ፡ የሚሰስንና ፡ የሚረክስ ፡ ሰው ፡ ቢኖር ፣ ፡ የሞት ፡ ፍርድን ፡ ይፍረዱበት ፣ ፡ እንደዚህ ፡ ካለው ፡ ሰው ፡ ራቁ ።'),
  ('1d3ffac7-ef89-589a-a298-57f4ccc1590f', 'dd5a559a-4398-5d26-ac16-138d56a83cff', 'cc0f84f3-0e14-5b2c-acfe-23797f702f98', 27, 27, 'ክርስቲያኖች ፡ ከሕግ ፡ የወጡ ፡ ሊሆኑና ፡ ክፉ ፡ በመሥራት ፡ ሊፈርዱ ፡ አግባብ ፡ አይደለም ።'),
  ('95dc6249-3cdd-5f35-a9ef-232bb0f44459', 'dd5a559a-4398-5d26-ac16-138d56a83cff', 'cc0f84f3-0e14-5b2c-acfe-23797f702f98', 28, 28, 'ነገር ፡ ግን ፡ ከወንጀለኞችና ፡ ከመናፍቃን ፣ ፡ ይለዩ ፣ ፡ ከእነርሱም ፡ ጋራ ፡ አንድ ፡ አይሁኑ ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('f9467812-9438-5eea-a135-5b4199094718', 'dd5a559a-4398-5d26-ac16-138d56a83cff', 'cc0f84f3-0e14-5b2c-acfe-23797f702f98', 29, 29, 'ስለ ፡ ክርስቶስ ፡ ስም ፡ ክርስቲያኖችን ፡ ወደ ፡ ግዞት ፡ ቤት ፡ ከሚያገቡ ፡ አስረውም ፡ ለሞት ፡ አሳልፈው ፡ ከሚሰጡ ፡ ከሓድያን ፡ ተጠበቁ ።'),
  ('b2d238f5-6eb6-5b59-a02c-b6ae1abf6c19', 'dd5a559a-4398-5d26-ac16-138d56a83cff', 'cc0f84f3-0e14-5b2c-acfe-23797f702f98', 30, 30, 'ወንድሞቻችሁንና ፡ ሰውነታችሁን ፡ ከከሐድያን ፡ እጅ ፡ አድኑ ።'),
  ('4e77df6b-7e93-53d2-a374-16ee9c96385f', 'dd5a559a-4398-5d26-ac16-138d56a83cff', 'cc0f84f3-0e14-5b2c-acfe-23797f702f98', 31, 31, 'ስለነርሱም ፡ የደከመ ፡ የክርስቲያን ፡ ወገን ፡ ቢገኝ ፡ ብፁዕ ፡ ነው ፣ ፡ ከሰማዕታት ፡ ጋራ ፡ ይቆጠራል ፣ ፡ ስለ ፡ ክርስቶስ ፡ መከራን ፡ ተቀብሏልና ።'),
