  ('e73defec-990f-5fe9-aebb-7d7ba97bc444', '3c30fc78-0b75-5a6f-af40-4a73b93c0ec6', '65ab8e9a-e4ac-5435-ac8e-da8dd0e83e34', 93, 93, 'እናንተ ፡ ግን ፡ ደስ ፡ የሚያሰኝ ፡ የዕውቀት ፡ ፍሬን ፡ ለማድረግ ፡ መንፈሳዊ ፡ ቅንዓትን ፡ ቅኑ ፣ ፡ እናንተን ፡ ቀድሞ ፡ ወደ ፡ ወይን ፡ ቦታ ፡ ልኳልና ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('04e419cc-9e25-569b-ac1d-9b9a755b9ef7', '3c30fc78-0b75-5a6f-af40-4a73b93c0ec6', '65ab8e9a-e4ac-5435-ac8e-da8dd0e83e34', 94, 94, 'እነርሱ ፡ ግን ፡ አይሰሟቸውም ፣ ፡ ልቡናቸውን ፡ አደንድነዋልና ።'),
  ('0546e575-f06b-5c35-a904-c1122a47cb6f', '3c30fc78-0b75-5a6f-af40-4a73b93c0ec6', '65ab8e9a-e4ac-5435-ac8e-da8dd0e83e34', 95, 95, 'የእግዚአብሔርን ፡ ወይን ፡ በሚጠብቁ ፡ ላይ ፡ ተነሣስተው ፡ ይዘው ፡ የገደሉት ፡ አለ ፣ ፡ በድንጋይ ፡ ወገሩት ፡ አለ ፣ ፡ በሰይፍ ፡ የገደሉት ፡ አለ ፣ ፡ በመጋዝ ፡ የተረተሩት ፡ አለ ፣ ፡ በቤተ ፡ መቅደስ ፡ ውስጥ ፡ የገደሉትም ፡ አለ ።'),
  ('31bbb8a2-036b-53ba-a637-3c4d75586dee', '3c30fc78-0b75-5a6f-af40-4a73b93c0ec6', '65ab8e9a-e4ac-5435-ac8e-da8dd0e83e34', 96, 96, 'ዳግመኛም ፡ ወራሹን ፡ ገደሉት ። አናጢዎች ፡ የናቁት ፡ ድንጊያንም ፡ ናቁት ።'),
  ('2535b3c3-ee5f-5960-aa43-7a55def4eb42', '3c30fc78-0b75-5a6f-af40-4a73b93c0ec6', '65ab8e9a-e4ac-5435-ac8e-da8dd0e83e34', 97, 97, 'ስለ ፡ እናንተም ፡ ፈንታ ፡ የማያውቀኝ ፡ ሕዝብ ፡ ተገዛልኝ ፣ ፡ በጀሮ ፡ መስሚያ ፡ ውስጥ ፡ መለሱልኝ ፡ አለ ።'),
  ('f44aa42e-7798-593f-a0cb-f3e417b9cec3', 'de74ba90-2c6f-5f39-a5d7-7bf30603255d', '5832bc83-c4f3-5bf1-a2e5-eca8feff0e12', 1, 1, 'ክርስቶስ ፡ በከበረ ፡ ደሙ ፡ የዋጃችሁ ፡ የተወደዳችሁ ፡ ወንድሞች ፡ ሆይ ፡ የቅድስት ፡ ፋሲካን ፡ በዓል ፡ በፍጹም ፡ መረዳትና ፡ ማስተዋል ፡ ታደርጉ ፡ ዘንድ ፡ ለእናንተ ፡ አገባብ ፡ ነው ።'),
  ('6962eb9d-18e1-5e78-a31d-a4d82eeeb5e7', 'de74ba90-2c6f-5f39-a5d7-7bf30603255d', '5832bc83-c4f3-5bf1-a2e5-eca8feff0e12', 2, 2, 'በመጋቢት ፡ ወር ፡ ፳፭ኛው ፡ ቀን ፡ መዓልትና ፡ ሌሊት ፡ ይተካከላልና ።'),
  ('1a0d62b9-9d3f-5a39-a69a-c483d2ad11eb', 'de74ba90-2c6f-5f39-a5d7-7bf30603255d', '5832bc83-c4f3-5bf1-a2e5-eca8feff0e12', 3, 3, 'እንግዲህ ፡ ቍጥርን ፡ ተረዱ ፣ ፡ ጌታችን ፡ በአንዲት ፡ ዓመት ፡ ሁለት ፡ ጊዜ ፡ አልታመመምና ፣ እናንተም ፡ የሕማማቱን ፡ መታሰቢያ ፡ በዓመት ፡ አንድ ፡ ጊዜ ፡ ታደርጉ ፡ ዘንድ ፡ ተጠንቀቁ ፣ ፡ ስለ ፡ እኛ ፡ ሙቷልና ።'),
  ('343b09d8-82d7-5832-a52e-0fab19bbec45', 'de74ba90-2c6f-5f39-a5d7-7bf30603255d', '5832bc83-c4f3-5bf1-a2e5-eca8feff0e12', 4, 4, 'ከአይሁድም ፡ ጋር ፡ በዓልን ፡ አታድርጉ ፣ ፡ በእኛና ፡ በእነርሱ ፡ መካከል ፡ ፍቅር ፡ የለምና ፣ ፡ እነርሱ ፡ የሚፈጽሙ ፡ እየመሰላቸው ፡ የቁጥር ፡ ዕውቀትን ፡ በስንፍና ፡ ስተዋል ።'),
  ('6af5c76b-41f2-5724-a646-1fcd0d7620ac', 'de74ba90-2c6f-5f39-a5d7-7bf30603255d', '5832bc83-c4f3-5bf1-a2e5-eca8feff0e12', 5, 5, 'ስለዚህም ፡ በምድር ፡ ላይ ፡ የታሠሩ ፡ ከጽድቅም ፡ የወጡ ፡ ሆነ ።'),
  ('55308af7-e125-5a3c-a5cb-9da90c2eceb4', 'de74ba90-2c6f-5f39-a5d7-7bf30603255d', '5832bc83-c4f3-5bf1-a2e5-eca8feff0e12', 6, 6, 'እናንተ ፡ ግን ፡ በዕብራውያን ፡ አቈጣጠር ፡ የመጋቢት ፡ ወር ፡ ሃያ ፡ አምስትተኛ ፡ ቀን ፡ ቍጥርን ፡ ጠብቁ ።'),
  ('2fef46b7-0e36-591e-a932-8f9a7e4d3e42', 'de74ba90-2c6f-5f39-a5d7-7bf30603255d', '5832bc83-c4f3-5bf1-a2e5-eca8feff0e12', 7, 7, 'ይህን ፡ ቁጥር ፡ እስከ ፡ ሃያ ፡ አንደኛው ፡ ሠርቀ ፡ ሌሊት ፡ ድረስ ፡ ጠብቁ ።'),
  ('9cd0b9a8-e550-5176-aec3-0ec2565b3edf', 'de74ba90-2c6f-5f39-a5d7-7bf30603255d', '5832bc83-c4f3-5bf1-a2e5-eca8feff0e12', 8, 8, 'ዳግመኛም ፡ የፍስሕን ፡ አቈጣጠር ፡ አታሳስቱ ፣ ፡ ከሆሣዕና ፡ አስቀድሞ ፡ እንዳይሆን ። ፋሲካም ፡ ቍጥርን ፡ ባለመጠንቀቅ ፡ በአንድ ፡ ዓመት ፡ ሁላት ፡ ጊዜ ፡ እንዳይሆን ፣ ፡ የጌታችን ፡ የአምላካችንና ፡ የመድኃኒታችን ፡ የኢየሱስ ፡ ክርስቶስ ፡ ቅድስት ፡ ትንሣኤ ፡ በተቀደሰች ፡ የክርስቲያን ፡ ሰንበት ፡ ይሁን ፡ እንጂ ።'),
  ('5026eb06-e1bd-5ea0-a342-ddada925091b', 'de74ba90-2c6f-5f39-a5d7-7bf30603255d', '5832bc83-c4f3-5bf1-a2e5-eca8feff0e12', 9, 9, 'ዳግመኛም ፡ የተቀደሰች ፡ የፋሲካ ፡ ጾም ፡ ከሰኞ ፡ እስከ ፡ ዋዜማዋ ፡ ቀዳሚት ፡ ሰንበት ፡ ቀዳም ፡ ስዑር ፡ ይሁን ።'),
  ('a9df1d99-b822-5cf3-a0ad-1b850af88bc8', 'de74ba90-2c6f-5f39-a5d7-7bf30603255d', '5832bc83-c4f3-5bf1-a2e5-eca8feff0e12', 10, 10, 'በሕማማት ፡ ሳምንትም ፡ በጨው ፡ ከተሠራ ፡ ቂጣና ፡ ከውሀ ፡ በቀር ፡ ምንም ፡ አትብሉ ፡ አትጠጡ ።'),
  ('6ad17ef1-a86c-5de2-ab6a-73a0f57461d8', 'de74ba90-2c6f-5f39-a5d7-7bf30603255d', '5832bc83-c4f3-5bf1-a2e5-eca8feff0e12', 11, 11, 'በዚህ ፡ የጾም ፡ ወራት ፡ ሥጋ ፡ ከመብላት ፡ ጠጅ ፡ ከመጠጣት ፡ ተጠበቁ ፣ ፡ የልቅሶና ፡ የኀዘን ፡ ቀኖች ፡ ናቸውና ፣ ፡ ይልቁንም ፡ እኒህን ፡ ስድስቱን ፡ ቀኖች ።'),
  ('0748b2f4-3605-5008-a004-419ae66e3ec6', 'de74ba90-2c6f-5f39-a5d7-7bf30603255d', '5832bc83-c4f3-5bf1-a2e5-eca8feff0e12', 12, 12, 'መጾም ፡ የሚቻለው ፡ ሰው ፡ ቢኖር ፡ ሁለት ፡ ቀን ፡ ይታገሥ ፣ ፡ ባይችል ፡ ግን ፡ በየአንዳንዲቱ ፡ ቀን ፡ ይጹም ።'),
  ('e81a6664-95ce-5692-a47b-d4c275128c12', 'de74ba90-2c6f-5f39-a5d7-7bf30603255d', '5832bc83-c4f3-5bf1-a2e5-eca8feff0e12', 13, 13, 'ክፉ ፡ ሥራ ፡ ከመሥራትም ፡ ይጠበቅ ፣ ፡ ጌታችን ፡ የሙሽራ ፡ ሚዜዎች ፡ ሙሽራው ፡ ከእነርሱ ፡ ጋራ ፡ ሳለ ፡ መጾም ፡ አይችሉም ፣ ፡ ነገር ፡ ግን ፡ ሙሽራውን ፡ ከእነርሱ ፡ የሚወስዱበት ፡ ጊዜ ፡ ይመጣል ፣ ያን ፡ ጊዜ ፡ ይጾማሉ ፡ እንጂ ፡ ብሏልና ።'),
  ('f0dbea22-b397-5504-ac58-350df46a58a5', 'de74ba90-2c6f-5f39-a5d7-7bf30603255d', '5832bc83-c4f3-5bf1-a2e5-eca8feff0e12', 14, 14, 'በዚህ ፡ በስድስተኛው ፡ ቀን ፡ አይሁድ ፡ ጌታን ፡ ከእኛ ፡ ወሰዱት ፣ ፡ በመስቀል ፡ ላይም ፡ ሰቀሉት ፣ ፡ ከበደለኞችም ፡ ጋራ ፡ ቈጥረውታልና ።'),
  ('d49c44e2-29ba-5a7c-ac81-f71e721d575e', 'de74ba90-2c6f-5f39-a5d7-7bf30603255d', '5832bc83-c4f3-5bf1-a2e5-eca8feff0e12', 15, 15, 'ስለዚህም ፡ እኛ ፡ እንደሠራነው ፡ ትጾሙ ፡ ዘንድ ፡ እናዛችኋለን ፣ ፡ ወደ ፡ ሰማይ ፡ ካረገ ፡ በኋላ ፡ ሌሎችንም ፡ ቀኖች ፡ ረቡዕንና ፡ ዓርብን ፡ እስከ ፡ ዘጠኝ ፡ ሰዓት ፡ ይጹሙ ።'),
  ('eacd8a18-48b5-5cc1-a816-dcbed125e649', 'de74ba90-2c6f-5f39-a5d7-7bf30603255d', '5832bc83-c4f3-5bf1-a2e5-eca8feff0e12', 16, 16, 'ፀሐይ ፡ እስኪገባ ፡ ሊጾም ፡ የሚወድ ፡ ሰው ፡ ቢኖር ፡ ይጹም ።'),
  ('d35fcfb8-808c-585e-ab81-272087e95caa', 'de74ba90-2c6f-5f39-a5d7-7bf30603255d', '5832bc83-c4f3-5bf1-a2e5-eca8feff0e12', 17, 17, 'ከእንግዲህ ፡ በኋላ ፡ በቤተ ፡ ክርስቲያን ፡ ተሰብስባችሁ ፡ በምስጋና ፡ በጸሎት ፡ ኦሪትንና ፡ ነቢያትን ፣ ፡ የዳዊትንም ፡ መዝሙር ፡ እያነበባችሁ ፡ የሌሊቱን ፡ ሰዓት ፡ ዶሮ ፡ እስኪ ፡ ጮህ ፡ ድረስ ፡ ጠብቁ ።'),
  ('9f98c52f-4a11-5b27-a794-4f18c37cbc94', 'de74ba90-2c6f-5f39-a5d7-7bf30603255d', '5832bc83-c4f3-5bf1-a2e5-eca8feff0e12', 18, 18, 'ካጠመቃችሁም ፡ በኋላ ፡ በፍርሃትና ፡ በመንቀጥቀጥ ፡ ሁናችሁ ፡ ወንጌልን ፡ አንብቡ ፣ ፡ ለሕዝቡም ፡ የሚጠቅመውንና ፡ የነፍሳቸውን ፡ መድኃኒት ፡ አስተምሯቸው ።'),
  ('46895018-aefa-5b1e-a86b-2a0f687c6b6f', 'de74ba90-2c6f-5f39-a5d7-7bf30603255d', '5832bc83-c4f3-5bf1-a2e5-eca8feff0e12', 19, 19, 'እስራኤልም ፡ ወደ ፡ ንስሐ ፡ ይመለስና ፡ ከክህደት ፡ ይድን ፡ ዘንድ ፡ እግዚአብሔርን ፡ ለምኑት ፣ ፡ ፈራጁ ፡ ጲላጦስ ፡ እኔ ፡ ከዚህ ፡ ጻድቅ ፡ ሰው ፡ ደም ፡ ንጹሕ ፡ ነኝ ፡ ብሎ ፡ እጆቹን ፡ ታጥቧልና ።'),
  ('2269120f-0cc2-5442-a219-7e6766932a80', 'de74ba90-2c6f-5f39-a5d7-7bf30603255d', '5832bc83-c4f3-5bf1-a2e5-eca8feff0e12', 20, 20, 'እስራኤል ፡ ግን ፡ ደሙ ፡ በኛ ፡ ላይና ፡ በልጆቻችን ፡ ላይ ፡ ይሁን ፡ ብለው ፡ ጮሁ ።'),
  ('1ed275ec-910f-5d46-a9a1-342de45d7e7b', 'de74ba90-2c6f-5f39-a5d7-7bf30603255d', '5832bc83-c4f3-5bf1-a2e5-eca8feff0e12', 21, 21, 'ከዚህ ፡ በኋላ ፡ ጲላጦስ ፡ ንጉሣችሁን ፡ ልስቀለውን ፡ አላቸው ።'),
  ('687c43c5-17d7-5921-a5fb-aeda27ac52ab', 'de74ba90-2c6f-5f39-a5d7-7bf30603255d', '5832bc83-c4f3-5bf1-a2e5-eca8feff0e12', 22, 22, 'እነርሱም ፡ ያለ ፡ ቄሣር ፡ ንጉሥ ፡ የለንምና ፡ ስቀለው ፡ ስቀለው ፡ ብለው ፡ መለሱ ፣ ፡ ራሱን ፡ ንጉሥ ፡ የሚያደርግ ፡ ሁሉ ፡ የንጉሥ ፡ ከዳተኛ ፡ ነውና ።'),
  ('36fbd0ae-59b5-5284-a084-4fd93efd4fe2', 'de74ba90-2c6f-5f39-a5d7-7bf30603255d', '5832bc83-c4f3-5bf1-a2e5-eca8feff0e12', 23, 23, 'ይህን ፡ ብታድነው ፡ የቄሣር ፡ ወዳጁ ፡ እይደለህም ፡ ብለው ፡ መለሱ ።'),
  ('bc9ea143-d0ed-5fa7-aa97-61693c2939af', 'de74ba90-2c6f-5f39-a5d7-7bf30603255d', '5832bc83-c4f3-5bf1-a2e5-eca8feff0e12', 24, 24, 'ከዚህም ፡ በኋላ ፡ ንጉሥ ፡ ሄሮድስና ፡ መስፍኑ ፡ ጲላጦስ ፡ ይሰቅሉት ፡ ዘንድ ፡ አዘዙ ፣ ፡ «አሕዛብ ፡ ለምን ፡ ዶለቱ? ፡ ሕዝቡስ ፡ ከንቱን ፡ ለምን ፡ ተናገሩ? ፡ የምድር ፡ ነገሥታትስ ፡ ለምን ፡ ተነሡ? ፡ አለቆችስ ፡ ከእነርሱ ፡ ጋራ ፡ ለምን ፡ ተሰበሰቡ? ፡ በእግዚአብሔርና ፡ በመሲሑ ፡ ላይ ፡ ለምን ፡ ተሰበሰቡ? ፡ ሁለተኛም ፡ ወንድማቸውን ፡ እንደ ፡ ርኩስ ፡ በድን ፡ ጣሉ?» ፡ አለ ፡ ተብሎ ፡ የተጻፈው ፡ ይፈጸም ፡ ዘንድ ።'),
  ('3e15c3d0-ed22-504d-af0d-c5036712d197', 'de74ba90-2c6f-5f39-a5d7-7bf30603255d', '5832bc83-c4f3-5bf1-a2e5-eca8feff0e12', 25, 25, 'ከዚህ ፡ በኋላም ፡ ዓርብ ፡ ቀን ፡ ሰቀሉት ፣ ፡ ተሰቅሎ ፡ በሞተ ፡ በሦስተኛው ፡ ቀን ፡ ተነሣ ፣ ፡ መጽሐፍ ፡ አቤቱ ፡ «ተነሥተሀ ፡ ምድርን ፡ ግዛት ፣ ፡ አንተ ፡ አሕዛብን ፡ ሁሉ ፡ ትወርሳለህና» ፡ ያለው ፡ ተፈጸመ ።'),
  ('7714ad4b-6723-5d5a-a403-26571371d807', 'de74ba90-2c6f-5f39-a5d7-7bf30603255d', '5832bc83-c4f3-5bf1-a2e5-eca8feff0e12', 26, 26, 'ዳግመኛም ፡ እግዚአብሔር ፡ ዛሬ ፡ ተነሥቼ ፡ መድኃኒትነትን ፡ አደርጋለሁ ፡ እገለጽበታላሁም ፡ አለ ።'),
  ('0bae9147-6c94-54b7-a15b-84c543ed51d8', 'de74ba90-2c6f-5f39-a5d7-7bf30603255d', '5832bc83-c4f3-5bf1-a2e5-eca8feff0e12', 27, 27, 'ሁለተኛም ፡ አቤቱ ፡ በቍጣህ ፡ ተነሥ ፣ ፡ በጠላቶችህም ፡ ላይ ፡ ከፍ ፡ ከፍ ፡ በል ፡ አለ ፣ ፡ ዳግመኛም ፡ ፍዳቸውን ፡ በራሳቸው ፡ ላይ ፡ አምጣባቸው ፡ አለ ።'),
