  ('3862d895-11dc-5bf3-a966-1a476028e58e', 'ce1aa0f9-aec3-5591-ae29-b3dd2b08f65a', '1d60ad62-ac0b-5e3a-a4b8-a68b06f53c5a', 72, 72, 'እኛም ፡ ከአንድ ፡ ቦታ ፡ ተሰብስበን ፡ ሳለ ፡ ክብርት ፡ የምትሆን ፡ ይህችን ፡ መልእክት ፡ ወደ ፡ እናንተ ፡ ላክን ።'),
  ('a3f0ca8f-88b9-5e83-a74c-b7394f617c78', 'ce1aa0f9-aec3-5591-ae29-b3dd2b08f65a', '1d60ad62-ac0b-5e3a-a4b8-a68b06f53c5a', 73, 73, 'እናንተም ፡ ሁሉ ፡ በእርሱ ፡ ቃልነት ፡ በተፈጠረ ፡ በክርስቶስ ፡ ያመናችሁ ፡ ወንድሞች ፡ ምእመናን ፡ ሆይ ፣ ፡ አሁንም ፡ ሁሉን ፡ የፈጠረ ፡ አንድ ፡ አምላክ ፡ እንደ ፡ ሆነ ፡ ያለ ፡ እርሱም ፡ ሌላ ፡ አምላክ ፡ እንደሌለ ፡ እንነግራችኋለን ።'),
  ('6b5575e7-62ab-5fe5-aeab-4739f7ddef8f', 'ce1aa0f9-aec3-5591-ae29-b3dd2b08f65a', '1d60ad62-ac0b-5e3a-a4b8-a68b06f53c5a', 74, 74, 'እሱን ፡ ታመልኩ ፡ ዘንድ ፡ ለእርሱም ፡ ትሰግዱ ፡ ዘንድ ፣ ለኢየሱስ ፡ ክርስቶስና ፡ ለመንፈስ ፡ ቅዱስም ፡ ትገዙ ፣ ዘንድ ፡ ቅዱሳት ፡ መጻሕፍትን ፡ ኦሪትንና ፡ ነቢያትንም ፡ ታነብሱ ፡ ዘንድ ፡ እናስተምራችኋለን ።'),
  ('16c9b787-10da-5f79-a6a9-f32611bb2d61', 'ce1aa0f9-aec3-5591-ae29-b3dd2b08f65a', '1d60ad62-ac0b-5e3a-a4b8-a68b06f53c5a', 75, 75, 'አባቶቻችሁን ፡ አክብሩ ፣ ፡ ከሕግ ፡ ጋራ ፡ መቃወምን ፡ ከሚቃወም ፡ ሁሉ ፡ ተለዩ ፣ እናንተስ ፡ ትንሣኤኝና ፡ የፍርድ ፡ ቀንን ፡ እመኑ ።'),
  ('60a8b53b-fd6f-50b9-ad13-6fb7f01b5519', 'ce1aa0f9-aec3-5591-ae29-b3dd2b08f65a', '1d60ad62-ac0b-5e3a-a4b8-a68b06f53c5a', 76, 76, 'ለሁሉ ፡ እንደሥራው ፡ እንደሚከፍለው ፡ ጠብቁ ። ፍጥረት ፡ ሁሉ ፡ ከእግዚአብሔር ፡ ተገኝቷልና ፡ ከሰይጣንም ፡ አይደለም ።'),
  ('b34e5c12-666c-5503-a0d1-e6a7f9ac5a34', 'ce1aa0f9-aec3-5591-ae29-b3dd2b08f65a', '1d60ad62-ac0b-5e3a-a4b8-a68b06f53c5a', 77, 77, 'ነገር ፡ ግን ፡ ክፉ ፡ ሁሉ ፡ ከሰይጣን ፡ ነው ።'),
  ('fb651219-52c0-5db8-a690-f357382fc098', 'ce1aa0f9-aec3-5591-ae29-b3dd2b08f65a', '1d60ad62-ac0b-5e3a-a4b8-a68b06f53c5a', 78, 78, 'በሕግ ፡ የሚሆን ፡ ጋብቻም ፡ ነውርና ፡ ጉድለት ፡ የለበትም ። ከእግዚአብሔር ፡ የታዘዘ ፡ ነው ፡ እንጂ ፡ አስቀድሞ ፡ ወንድና ፡ ሴት ፡ አድርጎ ፡ ፈጥሮአቸዋልና ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('f0158a31-7e5e-5d2d-a76f-a263b2d61bd1', 'ce1aa0f9-aec3-5591-ae29-b3dd2b08f65a', '1d60ad62-ac0b-5e3a-a4b8-a68b06f53c5a', 79, 79, 'ስለዚህም ፡ እንዲህ ፡ አለ ፣ ሰው ፡ እናትና ፡ አባቱን ፡ ትቶ ፡ ሚስቱን ፡ ይከተላታል ፣ ሁለቱም ፡ አንድ ፡ አካልን ፡ ይሆናሉ ።'),
  ('014f66b3-7198-5bff-ad0d-b3a0b9f012a4', 'ce1aa0f9-aec3-5591-ae29-b3dd2b08f65a', '1d60ad62-ac0b-5e3a-a4b8-a68b06f53c5a', 80, 80, 'ካገባም ፡ በኋላ ፡ በዝሙት ፡ ብቻ ፡ እንጂ ፡ ሰው ፡ ሚስቱን ፡ አይፍታ ፣ አካሉ ፡ ናትና ። እኔ ፡ ፈጥሬያቸዋለሁና ፡ ሌላም ፡ አይደለም ።'),
  ('d2abca42-b59f-540b-a7ce-2e5274a3a26c', 'ce1aa0f9-aec3-5591-ae29-b3dd2b08f65a', '1d60ad62-ac0b-5e3a-a4b8-a68b06f53c5a', 81, 81, 'እንዲህም ፡ አለ ፣ እግዚአብሔር ፡ አንድ ፡ ያደረገውን ፡ ሰው ፡ አይለይ ። ሁለት ፡ አካል ፡ አድርጎ ፡ ከሚስቱ ፡ የሚለይ ፡ ሰው ፡ የእግዚአብሔርን ፡ ትእዛዝ ፡ አፈረሰ ።'),
  ('8f6b18e1-268d-5e1a-a0d0-2e8b5d5ea5f8', 'ce1aa0f9-aec3-5591-ae29-b3dd2b08f65a', '1d60ad62-ac0b-5e3a-a4b8-a68b06f53c5a', 82, 82, 'የተፈታችውንም ፡ ያገባ ፡ ሥጋውን ፡ አረከሰ ። ዘማዊቲቱንም ፡ የተከተለ ፡ ፈጽሞ ፡ ሕግን ፡ አፈረሰ ።'),
  ('7861c2a4-a5fa-5da9-ad21-123a21b4e91d', 'ce1aa0f9-aec3-5591-ae29-b3dd2b08f65a', '1d60ad62-ac0b-5e3a-a4b8-a68b06f53c5a', 83, 83, 'ዘማዊቲቱን ፡ ከሥጋህ ፡ ለያት ። ያንተ ፡ አልሆነችምና ።'),
  ('ab06bb97-0540-5d97-a00d-30c89b907fd3', 'ce1aa0f9-aec3-5591-ae29-b3dd2b08f65a', '1d60ad62-ac0b-5e3a-a4b8-a68b06f53c5a', 84, 84, 'እንግዲህ ፡ ሥጋችሁን ፡ አታርክሱ ። ለምእመናን ፡ በንጹሕ ፡ መንፈስ ፡ የልብ ፡ መገረዝ ፡ ይብቃቸዋልና ።'),
  ('e4b2663b-e7f2-518e-abdb-ffbd7422d08b', 'ce1aa0f9-aec3-5591-ae29-b3dd2b08f65a', '1d60ad62-ac0b-5e3a-a4b8-a68b06f53c5a', 85, 85, 'ሁለተኛ ፡ ጥምቀትን ፡ አታድርጉ ። መጀመርያ ፡ የተጠመቃችሁት ፡ ይበቃችኋል ።'),
  ('d3ff055b-6766-51f4-acc5-321bf1cf526b', 'ce1aa0f9-aec3-5591-ae29-b3dd2b08f65a', '1d60ad62-ac0b-5e3a-a4b8-a68b06f53c5a', 86, 86, 'በክርስቶስ ፡ ሞት ፡ ተቀብራችኋልና ፡ ተጠምቃችኋልና ፡ ለከሐዲዎችና ፡ ለመናፍቃን ፡ ያልተሰጠች ፣ ፡ ነገር ፡ ግን ፡ ለቅዱሳን ፡ ካህናት ፡ በአብ ፡ በወልድ ፡ በመንፈስ ፡ ቅዱስ ፡ ስም ፡ የሰጠናችሁ ፡ ናት ።'),
  ('6cc014e6-9e95-57d9-adfc-92b589e93df2', 'ce1aa0f9-aec3-5591-ae29-b3dd2b08f65a', '1d60ad62-ac0b-5e3a-a4b8-a68b06f53c5a', 87, 87, 'ሃይማኖትን ፡ ከለወጡ ፡ ሰዎች ፣ ጥምቀትን ፡ አትቀበሉ ፣ ጥምቀት ፡ አንዲት ፡ ናትና ፡ እግዚአብሔር ፡ አብ ፡ አንድ ፡ ነው ። ጌታችንና ፡ መድኃኒታችን ፡ ኢየሱስ ፡ ክርስቶስም ፡ አንድ ፡ ነው ። መንፈስ ፡ ቅዱስ ፡ ጰራቅሊጦስም ፡ አንድ ፡ ነው ፣ ኢየሱስ ፡ ክርስቶስም ፡ በሥጋ ፡ የሞተው ፡ ሞት ፡ አንድ ፡ ነው ።'),
  ('d6fd1e94-7a8c-59f0-af7a-a619a383ac3b', 'ce1aa0f9-aec3-5591-ae29-b3dd2b08f65a', '1d60ad62-ac0b-5e3a-a4b8-a68b06f53c5a', 88, 88, 'እንዲሁ ፡ በሞቱ ፡ እምሳል ፡ የተቀበላችሁት ፡ ጥምቀትም ፡ አንድ ፡ ጊዜ ፡ ይሁን ።'),
  ('502c9014-c18b-5ed6-a0aa-ff88631f5e52', 'ce1aa0f9-aec3-5591-ae29-b3dd2b08f65a', '1d60ad62-ac0b-5e3a-a4b8-a68b06f53c5a', 89, 89, 'ነገር ፡ ግን ፡ የማያምን ፡ እንደዚህም ፡ የሚያደርግ ፡ ክፍሉ ፡ ከከሐዲዎችና ፡ ክፉ ፡ ትምህርት ፡ ከአላቸው ፡ ጋር ፡ ይሆናል ።'),
  ('f44e6951-a085-5eed-aaf1-77c9387606fe', 'ce1aa0f9-aec3-5591-ae29-b3dd2b08f65a', '1d60ad62-ac0b-5e3a-a4b8-a68b06f53c5a', 90, 90, 'እንደዚህ ፡ ለሚያደርጉ ፡ ሰዎችም ፡ እግዚአብሔር ፡ እንዲህ ፡ ይላል ፣ ፡ ‹‹ትምህርቴን ፡ ንቃችኋልና ፣ እኔም ፡ እንቃችኋለሁ ፣ እተዋችኋለሁ ፡ የካህናት ፡ አለቆችም ፡ አላደርጋችሁም ። ›› ፡'),
  ('a49c9940-84f3-5549-adb9-000f5848d715', 'ce1aa0f9-aec3-5591-ae29-b3dd2b08f65a', '1d60ad62-ac0b-5e3a-a4b8-a68b06f53c5a', 91, 91, 'ከእናንተም ፡ የሚጠመቁት ፡ ንጹሓን ፡ አይደሉም ፣ ፡ የኃጢአት ፡ ሥርየት ፡ የሌላቸው ፡ ርኩሳን ፡ ናቸው ፡ እንጂ ።'),
  ('0e10477c-bc32-54fa-afcb-99dd85d851c1', 'ce1aa0f9-aec3-5591-ae29-b3dd2b08f65a', '1d60ad62-ac0b-5e3a-a4b8-a68b06f53c5a', 92, 92, 'ሁለተኛ ፡ ጥምቀትን ፡ የሚቀበሉም ፡ እንዲሁ ፡ ይሆናሉ ፣ ፡ የክርስቶስንም ፡ ሥራ ፡ ጨዋታ ፡ ያደርጋሉ ፣ ፡ ቅዱሳንንም ፡ ይተናኮሏቸዋል ፣ ፡ በመንፈስ ፡ ቅዱስ ፡ ላይም ፡ ይሳደባሉ ፣ ፡ ክቡር ፡ ደሙንም ፡ ያረክሳሉ ፣ ፡ መከራዎቹንና ፡ ምስክርነቱንም ፡ ይክዳሉ ።'),
  ('44bc55c1-2628-58aa-a683-8b6402fea70c', 'ce1aa0f9-aec3-5591-ae29-b3dd2b08f65a', '1d60ad62-ac0b-5e3a-a4b8-a68b06f53c5a', 93, 93, 'በቀናች ፡ ሃይማኖት ፡ አምነው ፡ የማይጠመቁ ፡ ግን ፡ ከሕግ ፡ የወጡ ፡ ይሆናሉ ፡ ይፈረድባቸዋልም ። እነርሱ ፡ ደሰድቡታል ፡ እንጂ ፡ አያምነበትም ።'),
  ('f56128a7-fba5-5c78-a680-3459df93cdae', 'ce1aa0f9-aec3-5591-ae29-b3dd2b08f65a', '1d60ad62-ac0b-5e3a-a4b8-a68b06f53c5a', 94, 94, 'ጌታችን ፡ ዳግመኛ ፡ ከውሀና ፡ ከመንፈስ ፡ ቅዱስ ፡ ያልተወለደ ፡ ወደ ፡ መንግሥተ ፡ ሰማያት ፡ መግባት ፡ አይችልም ፣ ነገር ፡ ግን ፡ ያመነና ፡ የተጠመቀ ፡ ይድናል ፡ ያላመነ ፡ ግን ፡ ይፈረድበታል ፡ አለ ።'),
  ('b6aa4aaa-4373-5eea-aa6c-0d32dba46691', 'ce1aa0f9-aec3-5591-ae29-b3dd2b08f65a', '1d60ad62-ac0b-5e3a-a4b8-a68b06f53c5a', 95, 95, 'ኋላ ፡ እጠመቃለሁ ፡ ብሎ ፡ ጥምቀትን ፡ የሚያስቀር ፡ ግን ፡ ይፈረድበታል ፣ ፡ ከእግዚአብሔርም ፡ ይርቃል ።'),
